    secret: { id: "food_secret", en: "Food coma", ipa: "fuːd ˈkəʊmə", ru: "Пищевая кома", literalRu: "пищевая кома", meaningRu: "Сонливость и лень после очень сытной еды.", exampleEn: "After that pizza I'm in a food coma.", exampleRu: "После этой пиццы я в пищевой коме.", originRu: "Шутливый «медицинский» термин из Америки 1980-х — наука зовёт это postprandial somnolence.", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Food coma\"><ellipse cx=\"98\" cy=\"146\" rx=\"60\" ry=\"9\" fill=\"rgba(0,0,0,.25)\"/><path d=\"M48 138v-44c0-14 10-24 24-24h28c14 0 24 10 24 24v44z\" fill=\"#C96A86\"/><path d=\"M40 138v-30c0-8 5-13 13-13s13 5 13 13v30zM134 138v-30c0-8-5-13-13-13s-13 5-13 13v30z\" fill=\"#E08AA2\"/><path d=\"M60 138v-30c0-7 5-11 12-11h32c7 0 12 4 12 11v30z\" fill=\"#E89BB0\"/><circle cx=\"86\" cy=\"84\" r=\"26\" fill=\"#FFE0B5\"/><path d=\"M76 84c2-2 5-2 7 0M89 84c2-2 5-2 7 0\" fill=\"none\" stroke=\"#5A2A3A\" stroke-width=\"3\" stroke-linecap=\"round\"/><ellipse cx=\"86\" cy=\"98\" rx=\"6\" ry=\"4\" fill=\"#5A2A3A\"/><circle cx=\"73\" cy=\"92\" r=\"4\" fill=\"#F2B8C6\" opacity=\".7\"/><circle cx=\"99\" cy=\"92\" r=\"4\" fill=\"#F2B8C6\" opacity=\".7\"/><path d=\"M50 116c10 8 24 10 36 6\" fill=\"none\" stroke=\"#E0524E\" stroke-width=\"7\" stroke-linecap=\"round\"/><ellipse cx=\"148\" cy=\"128\" rx=\"30\" ry=\"9\" fill=\"#E7E3DA\"/><ellipse cx=\"148\" cy=\"125\" rx=\"24\" ry=\"6\" fill=\"#F2EFE6\"/><path d=\"M114 58a7 7 0 1 0-6-7 9 9 0 1 1 9 9\" fill=\"none\" stroke=\"#9AA6C0\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M132 40a5.5 5.5 0 1 0-5-5.5 7 7 0 1 1 7 7\" fill=\"none\" stroke=\"#9AA6C0\" stroke-width=\"3.4\" stroke-linecap=\"round\"/><path d=\"M146 26a4 4 0 1 0-3.6-4 5 5 0 1 1 5 5\" fill=\"none\" stroke=\"#9AA6C0\" stroke-width=\"3\" stroke-linecap=\"round\"/></svg>" },
