    secret: { id: "time_secret", en: "In a jiffy", ipa: "ɪn ə ˈdʒɪfi", ru: "Мигом, в два счёта", literalRu: "в один джиффи", meaningRu: "Очень-очень быстро, буквально за секунду.", exampleEn: "Hang on, I'll be back in a jiffy with the snacks.", exampleRu: "Подожди, я мигом вернусь с закусками.", originRu: "«Jiffy» — словечко XVIII века; забавно, что позже учёные сделали его настоящей единицей: в физике джиффи — время, за которое свет пробегает один сантиметр.", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"In a jiffy\"><ellipse cx=\"138\" cy=\"146\" rx=\"40\" ry=\"8\" fill=\"rgba(0,0,0,.25)\"/><path d=\"M10 70h44M4 88h54M14 106h40\" stroke=\"#FFE08A\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M24 78c30-6 60-6 84 4-26-2-52-2-78 6z\" fill=\"#FFD23F\" opacity=\".55\"/><path d=\"M150 30l-44 56 26-4-22 48 56-58-28 4z\" fill=\"#FFD23F\"/><path d=\"M150 30l-44 56 26-4-22 48\" stroke=\"#E8B800\" stroke-width=\"3\" fill=\"none\" stroke-linejoin=\"round\"/><circle cx=\"128\" cy=\"78\" r=\"3.6\" fill=\"#3A2230\"/><circle cx=\"142\" cy=\"74\" r=\"3.6\" fill=\"#3A2230\"/><path d=\"M128 90c5 3 12 1 15-3\" stroke=\"#3A2230\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M168 22l2 6 6 2-6 2-2 6-2-6-6-2 6-2z\" fill=\"#FFF3B0\"/><path d=\"M186 70l1.6 5 5 1.6-5 1.6-1.6 5-1.6-5-5-1.6 5-1.6z\" fill=\"#FFF3B0\"/><path d=\"M96 116l1.6 5 5 1.6-5 1.6-1.6 5-1.6-5-5-1.6 5-1.6z\" fill=\"#FFF3B0\"/><circle cx=\"180\" cy=\"44\" r=\"2.4\" fill=\"#FFF3B0\"/><circle cx=\"116\" cy=\"38\" r=\"2\" fill=\"#FFF3B0\"/></svg>" },
