    secret: { id: "sport_secret", en: "GG", ipa: "dʒiː ˈdʒiː", ru: "Хорошая игра!", literalRu: "джи-джи (good game)", meaningRu: "Дружеское «хорошая игра» в конце матча — признание достойной партии.", exampleEn: "Great match, everyone — GG!", exampleRu: "Отличный матч, ребята — хорошая игра!", originRu: "Сокращение от good game из мира видеоигр: соперники пишут «GG» в чате после боя как знак уважения. Иногда с подколом — «gg» в безнадёжно проигранной партии.", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"GG\"><ellipse cx=\"62\" cy=\"146\" rx=\"32\" ry=\"7\" fill=\"rgba(0,0,0,.25)\"/><ellipse cx=\"138\" cy=\"146\" rx=\"32\" ry=\"7\" fill=\"rgba(0,0,0,.25)\"/><rect x=\"62\" y=\"92\" width=\"76\" height=\"44\" rx=\"6\" fill=\"#3A4A6A\"/><rect x=\"70\" y=\"100\" width=\"60\" height=\"28\" rx=\"3\" fill=\"#6FB3D2\"/><path d=\"M84 114h32M100 106v16\" stroke=\"#FFF7DD\" stroke-width=\"3\" stroke-linecap=\"round\"/><ellipse cx=\"56\" cy=\"76\" rx=\"20\" ry=\"24\" fill=\"#C46AA8\"/><path d=\"M36 72c0-12 9-20 20-20s20 8 20 20z\" fill=\"#A4528C\"/><circle cx=\"60\" cy=\"74\" r=\"3.4\" fill=\"#16243A\"/><circle cx=\"72\" cy=\"74\" r=\"3.4\" fill=\"#16243A\"/><path d=\"M58 84c5 3 11 3 15 0\" stroke=\"#16243A\" stroke-width=\"2.8\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M74 86c10 4 16 10 16 16\" stroke=\"#C46AA8\" stroke-width=\"8\" fill=\"none\" stroke-linecap=\"round\"/><ellipse cx=\"144\" cy=\"76\" rx=\"20\" ry=\"24\" fill=\"#7FB069\"/><path d=\"M124 72c0-12 9-20 20-20s20 8 20 20z\" fill=\"#5E8A4A\"/><circle cx=\"128\" cy=\"74\" r=\"3.4\" fill=\"#16243A\"/><circle cx=\"140\" cy=\"74\" r=\"3.4\" fill=\"#16243A\"/><path d=\"M127 84c5 3 11 3 15 0\" stroke=\"#16243A\" stroke-width=\"2.8\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M126 86c-10 4-16 10-16 16\" stroke=\"#7FB069\" stroke-width=\"8\" fill=\"none\" stroke-linecap=\"round\"/><ellipse cx=\"100\" cy=\"104\" rx=\"11\" ry=\"8\" fill=\"#F2C9A0\"/><rect x=\"20\" y=\"24\" width=\"8\" height=\"8\" rx=\"2\" fill=\"#E0524E\" transform=\"rotate(20 24 28)\"/><rect x=\"170\" y=\"30\" width=\"8\" height=\"8\" rx=\"2\" fill=\"#FFD23F\" transform=\"rotate(-25 174 34)\"/><circle cx=\"46\" cy=\"22\" r=\"4\" fill=\"#6FB3D2\"/><circle cx=\"154\" cy=\"20\" r=\"4\" fill=\"#C46AA8\"/><rect x=\"96\" y=\"14\" width=\"8\" height=\"8\" rx=\"2\" fill=\"#7FB069\" transform=\"rotate(15 100 18)\"/><circle cx=\"122\" cy=\"30\" r=\"3.5\" fill=\"#FFD23F\"/><circle cx=\"78\" cy=\"28\" r=\"3.5\" fill=\"#E0524E\"/></svg>" },
