    secret: { id: "music_secret", en: "A banger", ipa: "ə ˈbæŋə", ru: "Хитяра, мощный трек", literalRu: "грохотушка", meaningRu: "Невероятно крутая, заводная песня, под которую хочется танцевать.", exampleEn: "Turn it up — this song is an absolute banger!", exampleRu: "Сделай погромче — эта песня просто хитяра!", originRu: "Сленг вырос из британской клубной сцены: «banger» буквально «то, что бахает», ведь мощный бит будто бьёт по ушам. О треках так говорят с конца 1990-х.", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"A banger\"><ellipse cx=\"100\" cy=\"150\" rx=\"50\" ry=\"8\" fill=\"rgba(0,0,0,.25)\"/><rect x=\"56\" y=\"64\" width=\"88\" height=\"74\" rx=\"8\" fill=\"#3A4A6A\"/><rect x=\"56\" y=\"64\" width=\"88\" height=\"74\" rx=\"8\" fill=\"none\" stroke=\"#2A3A56\" stroke-width=\"3\"/><circle cx=\"80\" cy=\"100\" r=\"18\" fill=\"#1E2A44\"/><circle cx=\"80\" cy=\"100\" r=\"12\" fill=\"#6FB6D6\"/><circle cx=\"80\" cy=\"100\" r=\"5\" fill=\"#16243A\"/><circle cx=\"120\" cy=\"100\" r=\"18\" fill=\"#1E2A44\"/><circle cx=\"120\" cy=\"100\" r=\"12\" fill=\"#E8638E\"/><circle cx=\"120\" cy=\"100\" r=\"5\" fill=\"#16243A\"/><rect x=\"64\" y=\"72\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#FFD23F\"/><rect x=\"126\" y=\"72\" width=\"14\" height=\"6\" rx=\"3\" fill=\"#7FB069\"/><path d=\"M40 100c-6-4-6-12 0-16M30 104c-10-6-10-22 0-28M160 100c6-4 6-12 0-16M170 104c10-6 10-22 0-28\" stroke=\"#6FB6D6\" stroke-width=\"4\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M100 36l5 14 14 1-10 9 4 14-13-8-13 8 4-14-10-9 14-1z\" fill=\"#FFD23F\"/><path d=\"M40 44l-6 14 14-3z\" fill=\"#F6C744\"/><path d=\"M160 44l6 14-14-3z\" fill=\"#F6C744\"/><path d=\"M58 30l3 9 9 1-7 6 2 9-7-5-7 5 2-9-7-6 9-1z\" fill=\"#F4D03F\"/><path d=\"M142 30l3 9 9 1-7 6 2 9-7-5-7 5 2-9-7-6 9-1z\" fill=\"#F4D03F\"/><path d=\"M100 22l4-10 4 10z\" fill=\"#FFE38F\"/></svg>" },
