    secret: { id: "clothes_secret", en: "Sunday best", ipa: "ˈsʌndeɪ best", ru: "Парадный наряд", literalRu: "воскресное лучшее", meaningRu: "Самая красивая и нарядная одежда, что у тебя есть.", exampleEn: "Grandpa put on his Sunday best for the wedding.", exampleRu: "Дедушка надел свой парадный наряд на свадьбу.", originRu: "От старого обычая надевать самую лучшую одежду по воскресеньям, идя в церковь. У многих был один-единственный нарядный комплект — его и звали «воскресным лучшим».", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Sunday best\"><ellipse cx=\"74\" cy=\"150\" rx=\"34\" ry=\"8\" fill=\"rgba(0,0,0,.25)\"/><rect x=\"120\" y=\"22\" width=\"62\" height=\"128\" rx=\"14\" fill=\"#C9A86A\"/><rect x=\"128\" y=\"30\" width=\"46\" height=\"112\" rx=\"8\" fill=\"#DCEEF5\"/><path d=\"M132 34l30 104\" stroke=\"#FFFFFF\" stroke-width=\"6\" stroke-linecap=\"round\" opacity=\".6\"/><path d=\"M150 38l14 92\" stroke=\"#FFFFFF\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\".5\"/><path d=\"M50 150v-44c0-14 11-24 24-24s24 10 24 24v44z\" fill=\"#5468C8\"/><path d=\"M64 106l10 16 10-16-4-8H68z\" fill=\"#EDEFF7\"/><path d=\"M70 112l4 6 4-6-2-4h-4z\" fill=\"#E0524E\"/><circle cx=\"74\" cy=\"60\" r=\"18\" fill=\"#F2C28B\"/><path d=\"M56 56c0-12 8-18 18-18s18 6 18 18c-5-4-12-6-18-6s-13 2-18 6z\" fill=\"#5A3A28\"/><circle cx=\"67\" cy=\"61\" r=\"2.8\" fill=\"#2A1830\"/><circle cx=\"81\" cy=\"61\" r=\"2.8\" fill=\"#2A1830\"/><path d=\"M67 71c4 3 10 3 14 0\" stroke=\"#2A1830\" stroke-width=\"2.6\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"74\" cy=\"90\" r=\"4\" fill=\"#E0524E\"/><path d=\"M74 90l-12 5 12-2 12 2z\" fill=\"#C13B37\"/><path d=\"M150 60l2.5 6 6 2.5-6 2.5-2.5 6-2.5-6-6-2.5 6-2.5z\" fill=\"#FFD23F\"/><path d=\"M158 104l2 5 5 2-5 2-2 5-2-5-5-2 5-2z\" fill=\"#FFD23F\"/><circle cx=\"146\" cy=\"92\" r=\"2.6\" fill=\"#FFFFFF\"/></svg>" },
