    secret: { id: "sea_secret", en: "Catfish", ipa: "ˈkætfɪʃ", ru: "Фейк под чужой личиной", literalRu: "сом", meaningRu: "Тот, кто выдаёт себя в сети за другого человека, чтобы обмануть.", exampleEn: "She turned out to be a catfish using someone else's photos.", exampleRu: "Она оказалась фейком, который выдавал себя за другого по чужим фото.", originRu: "Слово в этом значении пришло из документального фильма «Catfish» (2010): в нём прозвучала байка, что сомов подсаживали к треске в бочках, чтобы рыба не дремала, — как обманщики «бодрят» жертву онлайн.", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Catfish\"><rect x=\"0\" y=\"0\" width=\"200\" height=\"160\" fill=\"#3E7CA8\"/><path d=\"M0 100h200v60H0z\" fill=\"#2E6090\"/><path d=\"M20 40c2 22-2 36-2 52M180 44c-2 20 2 34 2 50\" stroke=\"#4FB37A\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\" opacity=\".7\"/><ellipse cx=\"100\" cy=\"150\" rx=\"46\" ry=\"7\" fill=\"rgba(0,0,0,.25)\"/><ellipse cx=\"86\" cy=\"92\" rx=\"40\" ry=\"28\" fill=\"#6E7A86\"/><path d=\"M48 92l-22-14v28z\" fill=\"#5A646E\"/><path d=\"M70 110c-6 6-10 14-10 22M88 112c-2 8-1 16 2 22\" stroke=\"#5A646E\" stroke-width=\"5\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M64 84c-14 2-26 0-36-8M64 96c-14 4-26 4-38 0\" stroke=\"#4A545E\" stroke-width=\"2.6\" fill=\"none\" stroke-linecap=\"round\"/><ellipse cx=\"132\" cy=\"88\" rx=\"28\" ry=\"32\" fill=\"#F2A03D\"/><path d=\"M160 88l16-12v24z\" fill=\"#F2A03D\"/><path d=\"M132 56c-3 6-5 10-5 14M132 120c-3-6-5-10-5-14\" stroke=\"#E0872C\" stroke-width=\"4\" stroke-linecap=\"round\"/><circle cx=\"124\" cy=\"82\" r=\"6.5\" fill=\"#FFFFFF\"/><circle cx=\"125\" cy=\"82\" r=\"3.4\" fill=\"#16243A\"/><path d=\"M114 98c8 5 18 5 26 0\" stroke=\"#C56F22\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M108 100c-6-4-12-4-20 0\" stroke=\"#6E7A86\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>" },
