    secret: { id: "sky_secret", en: "Space out", ipa: "speɪs aʊt", ru: "Залипнуть, улететь мыслями", literalRu: "уйти в космос", meaningRu: "Отключиться, перестать соображать и витать где-то в мыслях.", exampleEn: "Sorry, I totally spaced out — what did you say?", exampleRu: "Прости, я совсем улетел — что ты сказал?", originRu: "Сленг родом из 1960-х: о человеке, чьи мысли будто уплыли в открытый космос, подальше от происходящего вокруг.", svg: "<svg viewBox=\"0 0 200 160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Space out\"><ellipse cx=\"100\" cy=\"151\" rx=\"44\" ry=\"7\" fill=\"rgba(0,0,0,.25)\"/><circle cx=\"34\" cy=\"34\" r=\"2.4\" fill=\"#FFE08A\"/><circle cx=\"172\" cy=\"40\" r=\"2.4\" fill=\"#FFE08A\"/><circle cx=\"166\" cy=\"120\" r=\"2.2\" fill=\"#FFE08A\"/><path d=\"M52 148c-3-28 8-48 48-48s51 20 48 48z\" fill=\"#7C6A9C\"/><rect x=\"78\" y=\"118\" width=\"44\" height=\"16\" rx=\"6\" fill=\"#A99AC4\"/><circle cx=\"100\" cy=\"74\" r=\"40\" fill=\"#BFE6F2\" opacity=\".55\"/><circle cx=\"100\" cy=\"74\" r=\"40\" fill=\"none\" stroke=\"#9FD0EE\" stroke-width=\"3\"/><ellipse cx=\"100\" cy=\"86\" rx=\"30\" ry=\"22\" fill=\"#F6C8A0\"/><circle cx=\"89\" cy=\"84\" r=\"5\" fill=\"#FFFFFF\"/><circle cx=\"111\" cy=\"84\" r=\"5\" fill=\"#FFFFFF\"/><circle cx=\"90\" cy=\"85\" r=\"2\" fill=\"#3A2418\"/><circle cx=\"110\" cy=\"85\" r=\"2\" fill=\"#3A2418\"/><path d=\"M92 98h16\" stroke=\"#7A3A2A\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"78\" cy=\"58\" r=\"7\" fill=\"#F46B6B\"/><circle cx=\"122\" cy=\"54\" r=\"9\" fill=\"#6FB6D6\"/><circle cx=\"108\" cy=\"48\" r=\"5\" fill=\"#F6C744\"/><path d=\"M115 54h14\" stroke=\"#9FB8D6\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>" },
